const now = new Date();
const leads = $input.all();

const followUpLeads = leads.filter(item => {
  const lead = item.json;
  if (!lead.Timestamp || lead['Follow Up Status'] === 'Completed') return false;

  const submittedAt = new Date(lead.Timestamp);
  const daysSince = Math.floor((now - submittedAt) / (1000 * 60 * 60 * 24));

  // Day 2: first check-in
  if (daysSince === 2 && lead['Follow Up Status'] === 'Scheduled') return true;
  // Day 5: additional options
  if (daysSince === 5 && lead['Follow Up Status'] === 'Day2Sent') return true;
  // Day 7: final follow-up
  if (daysSince === 7 && lead['Follow Up Status'] === 'Day5Sent') return true;

  return false;
}).map(item => {
  const lead = item.json;
  const submittedAt = new Date(lead.Timestamp);
  const daysSince = Math.floor((now - submittedAt) / (1000 * 60 * 60 * 24));

  let followUpType = 'day2';
  let subject = '';
  let body = '';

  if (daysSince === 2) {
    followUpType = 'day2';
    subject = `Still searching for ${lead['Property Type']} in ${lead.Location}?`;
    body = `Hi ${lead.Name},\n\nI wanted to check in and see if you had any questions about your property search in ${lead.Location}.\n\nOur team has been reviewing options in your price range (${lead.Budget}) and we'd love to share what we've found. Would you be available for a quick call this week?\n\nBest regards,\nYour LeadFlowAI Agent`;
  } else if (daysSince === 5) {
    followUpType = 'day5';
    subject = `New ${lead['Property Type']} listings in ${lead.Location} — just for you`;
    body = `Hi ${lead.Name},\n\nWe've just identified 3 new ${lead['Property Type']} listings in ${lead.Location} that match your criteria perfectly, all within your ${lead.Budget} budget.\n\nI'd love to set up viewings at your convenience. Simply reply to this email or call us directly.\n\nWarm regards,\nYour LeadFlowAI Agent`;
  } else if (daysSince === 7) {
    followUpType = 'day7';
    subject = `Final note on your property search, ${lead.Name.split(' ')[0]}`;
    body = `Hi ${lead.Name},\n\nThis is my final note regarding your property inquiry. I don't want to keep your inbox busy, but I wanted to make sure you found what you were looking for.\n\nIf you're still actively searching or have any questions, please don't hesitate to reach out — we're here to help you find the perfect ${lead['Property Type']} in ${lead.Location}.\n\nWith warm regards,\nYour LeadFlowAI Agent`;
  }

  return {
    json: {
      ...lead,
      followUpType,
      followUpSubject: subject,
      followUpBody: body,
      daysSince,
    }
  };
});

return followUpLeads;

const item = $input.first().json;
const statusMap = {
  day2: 'Day2Sent',
  day5: 'Day5Sent',
  day7: 'Completed'
};
return [{ json: { ...item, newStatus: statusMap[item.followUpType] || 'Scheduled' } }];
